  static public bool Verify(Google.FlatBuffers.Verifier verifier, uint tablePos)
  {
    return verifier.VerifyTableStart(tablePos)
      && verifier.VerifyField(tablePos, 4 /*InteractionLayers*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 6 /*DistanceKind*/, 1 /*Battlement.FlatBuffers.Generated.InteractionDistanceKind*/, 1, false)
      && verifier.VerifyField(tablePos, 8 /*MaximumInteractionDistance*/, 4 /*float*/, 4, false)
      && verifier.VerifyField(tablePos, 10 /*InputRedirection*/, 1 /*Battlement.FlatBuffers.Generated.PanelInputRedirection*/, 1, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}

}
